from PIL import Image
A=Image.open('p01-dark-row.png').convert('RGB')
B=Image.open('p01-dark-popover.png').convert('RGB')
pa=A.load(); pb=B.load()
W,H=B.size
def runs(p,y,x0,x1):
    out=[];prev=None;st=x0
    for x in range(x0,x1):
        c=p[x,y]
        if c!=prev:
            if prev is not None: out.append((st,x-1,prev))
            prev=c;st=x
    out.append((st,x1-1,prev));return out
def vruns(p,x,y0,y1):
    out=[];prev=None;st=y0
    for y in range(y0,y1):
        c=p[x,y]
        if c!=prev:
            if prev is not None: out.append((st,y-1,prev))
            prev=c;st=y
    out.append((st,y1-1,prev));return out
for y in (340,400):
    print('--- y=%d AFTER'%y)
    for r in runs(pb,y,360,745):
        if r[1]-r[0]>=1 or r[2]!=(38,38,38): print('   ',r)
print('--- BEFORE y=340')
for r in runs(pa,340,360,745): print('   ',r)
print('--- vertical x=700 (inside card, right of text)')
for r in vruns(pb,700,250,440): print('   ',r)
print('--- vertical x=390 (left inside)')
for r in vruns(pb,390,250,440): print('   ',r)
EOF
